using KBS.BLL.Interfaces; using KBS.Models.DTOs.Brands; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace KBS.API.Controllers;
[ApiController][Route("api/brands")] public class BrandsController(IBrandService service):ControllerBase { [AllowAnonymous][HttpGet] public Task<List<BrandResponseDto>> GetAll(CancellationToken ct)=>service.GetAllAsync(ct); [AllowAnonymous][HttpGet("{id:long}")] public async Task<ActionResult<BrandResponseDto>> Get(long id,CancellationToken ct){var x=await service.GetByIdAsync(id,ct);return x is null?NotFound():Ok(x);}[Authorize(Roles="Admin")][HttpPost] public async Task<ActionResult<BrandResponseDto>> Create(BrandCreateDto dto,CancellationToken ct){try{var x=await service.CreateAsync(dto,ct);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}catch(ArgumentException e){return BadRequest(new{message=e.Message});}catch(InvalidOperationException e){return Conflict(new{message=e.Message});}}[Authorize(Roles="Admin")][HttpPut("{id:long}")] public async Task<ActionResult<BrandResponseDto>> Update(long id,BrandUpdateDto dto,CancellationToken ct){try{var x=await service.UpdateAsync(id,dto,ct);return x is null?NotFound():Ok(x);}catch(ArgumentException e){return BadRequest(new{message=e.Message});}catch(InvalidOperationException e){return Conflict(new{message=e.Message});}} }
